-- Adds the Kotlin syntax list of src/plugins/packs/commands.json (v0.68.0) to workspaces saved before it, as
-- 0009_seed_command_lists does for the other command lists and with the same rules: a list with its id or name is kept
-- as it is, and a workspace that would go over 100 lists or the size the app saves (MaxListsBytes) is left as it is.
WITH pack AS (
  SELECT list, position FROM jsonb_array_elements('[{"id":"kotlin-syntax","name":"Kotlin構文","words":[{"display":"fun main() { println(\"Hello, Kotlin!\") }","input":"fun main() { println(\"Hello, Kotlin!\") }","annotation":"fun main()：実行開始の関数（関数をトップレベルに定義可能） / コード例の利用：断片を適切な場所へ配置（多くの例は関数内の断片。未定義の変数・型・関数・import等を補って利用）"},{"display":"fun greet() {}","input":"fun greet() {}","annotation":"fun：関数定義"},{"display":"println(\"Hello\")","input":"println(\"Hello\")","annotation":"println：表示して改行（標準ライブラリ）"},{"display":"package example.app","input":"package example.app","annotation":"package：パッケージ宣言"},{"display":"import kotlin.math.sqrt","input":"import kotlin.math.sqrt","annotation":"import：型・関数等を読み込む"},{"display":"// コメント","input":"// コメント","annotation":"//：1行コメント"},{"display":"/* コメント */","input":"/* コメント */","annotation":"/* ... */：複数行コメント（入れ子にできる）"},{"display":"/** 利用者の情報。 */","input":"/** 利用者の情報。 */","annotation":"/** ... */：KDocコメント（宣言の前に配置）"},{"display":"val n = 1; println(n)","input":"val n = 1; println(n)","annotation":"文末のセミコロン省略：通常の文の区切り（通常は行末の;が不要）"},{"display":"val age = 20","input":"val age = 20","annotation":"val：再代入できない変数（参照先の内部まで変更不可になるわけではない）"},{"display":"var count = 0","input":"var count = 0","annotation":"var：再代入できる変数"},{"display":"val age: Int = 20","input":"val age: Int = 20","annotation":"名前: 型：型を明示"},{"display":"count = 1","input":"count = 1","annotation":"=：代入（countはvarで宣言済み）"},{"display":"const val MAX = 100","input":"const val MAX = 100","annotation":"const val：コンパイル時定数（トップレベル・object・companion object内等。型と初期値に制約）"},{"display":"val n = age.toLong()","input":"val n = age.toLong()","annotation":"toLong()：数値型変換（通常、数値型間の代入変換を明示）"},{"display":"val n = \"123\".toInt()","input":"val n = \"123\".toInt()","annotation":"toInt()：文字列を整数へ（形式が不正なら例外）"},{"display":"val n = \"abc\".toIntOrNull()","input":"val n = \"abc\".toIntOrNull()","annotation":"toIntOrNull()：失敗時にnullとなる変換（結果はInt?）"},{"display":"val n: Int; n = 1; println(n)","input":"val n: Int; n = 1; println(n)","annotation":"初期化：使用前に値を設定（変数・プロパティは適切な初期化が必要）"},{"display":"val n: Long = 100L","input":"val n: Long = 100L","annotation":"Byte / Short / Int / Long：整数"},{"display":"val f = 0.5f; val d = 0.5","input":"val f = 0.5f; val d = 0.5","annotation":"Float / Double：浮動小数点数"},{"display":"val ok: Boolean = true","input":"val ok: Boolean = true","annotation":"Boolean：真偽値"},{"display":"val c: Char = ''A''","input":"val c: Char = ''A''","annotation":"Char：UTF-16コード単位（すべてのUnicode文字が1つのCharで表せるわけではない）"},{"display":"val name: String = \"Pomo\"","input":"val name: String = \"Pomo\"","annotation":"String：文字列（文字列自体は不変）"},{"display":"val value: Any = 1","input":"val value: Any = 1","annotation":"Any：非null型の共通の上位型（nullも扱うならAny?）"},{"display":"fun greet(): Unit { println(\"Hello\") }","input":"fun greet(): Unit { println(\"Hello\") }","annotation":"Unit：意味のある結果を返さない型（通常は戻り値型を省略）"},{"display":"fun fail(): Nothing = throw IllegalStateException(\"失敗\")","input":"fun fail(): Nothing = throw IllegalStateException(\"失敗\")","annotation":"Nothing：正常に戻らない処理の型"},{"display":"val message = \"こんにちは、$name\"","input":"val message = \"こんにちは、$name\"","annotation":"$変数：文字列テンプレート"},{"display":"val detail = \"長さは${name.length}です\"","input":"val detail = \"長さは${name.length}です\"","annotation":"${式}：式を文字列へ埋め込む"},{"display":"val text = \"\"\"1行目 2行目\"\"\"","input":"val text = \"\"\"1行目 2行目\"\"\"","annotation":"\"\"\"...\"\"\"：raw文字列（改行を含められる。バックスラッシュのエスケープは解釈しない）"},{"display":"val remainder = 10 % 3","input":"val remainder = 10 % 3","annotation":"+ - * / %：加減乗除・余り（整数同士の除算は小数部を切り捨て）"},{"display":"val same = name == \"Pomo\"","input":"val same = name == \"Pomo\"","annotation":"==：内容に基づく等値比較（equalsに基づく。型による特性がある）"},{"display":"val sameReference = a === b","input":"val sameReference = a === b","annotation":"===：参照の同一性（プリミティブ相当値等の同一性に依存しない）"},{"display":"val adult = age >= 20","input":"val adult = age >= 20","annotation":"< <= > >=：大小比較"},{"display":"val ok = enabled && !blocked","input":"val ok = enabled && !blocked","annotation":"&& || !：論理演算（&&と||は短絡評価）"},{"display":"count += 2","input":"count += 2","annotation":"+= / -=：計算と代入（型によって代入演算子関数として処理）"},{"display":"count++","input":"count++","annotation":"++ / --：1増減"},{"display":"val valid = age in 18..65","input":"val valid = age in 18..65","annotation":"in / !in：所属判定（範囲・コレクション等に使用）"},{"display":"val label = if (age >= 20) { \"成人\" } else { \"未成年\" }","input":"val label = if (age >= 20) { \"成人\" } else { \"未成年\" }","annotation":"if / else：条件分岐・値の選択（三項演算子はなくif式を使う）"},{"display":"val label = when (role) { \"admin\" -> \"管理者\"; \"member\", \"guest\" -> \"一般利用者\"; else -> \"不明\" }","input":"val label = when (role) { \"admin\" -> \"管理者\"; \"member\", \"guest\" -> \"一般利用者\"; else -> \"不明\" }","annotation":"when (値)：値で分岐（式として使う場合は網羅が必要）"},{"display":"val result = when { score >= 80 -> \"優\"; score >= 60 -> \"良\"; else -> \"再挑戦\" }","input":"val result = when { score >= 80 -> \"優\"; score >= 60 -> \"良\"; else -> \"再挑戦\" }","annotation":"when { 条件 -> ... }：条件を順に判定"},{"display":"val label = when (n) { in 1..10 -> \"範囲内\"; else -> \"範囲外\" }","input":"val label = when (n) { in 1..10 -> \"範囲内\"; else -> \"範囲外\" }","annotation":"when内のin：範囲で分岐"},{"display":"val label = when (value) { is String -> \"文字列\"; else -> \"その他\" }","input":"val label = when (value) { is String -> \"文字列\"; else -> \"その他\" }","annotation":"when内のis：型で分岐"},{"display":"else -> \"不明\"","input":"else -> \"不明\"","annotation":"else ->：その他の場合（whenブロック内で使用）"},{"display":"for (item in items) { println(item) }","input":"for (item in items) { println(item) }","annotation":"for (item in items)：要素を順に処理（Javaの3部構成forはない）"},{"display":"for (i in 0..4) println(i)","input":"for (i in 0..4) println(i)","annotation":"..：両端を含む範囲（0〜4）"},{"display":"for (i in 0..<5) println(i)","input":"for (i in 0..<5) println(i)","annotation":"..<：上端を含まない範囲（0以上5未満）"},{"display":"for (i in 0 until 5) println(i)","input":"for (i in 0 until 5) println(i)","annotation":"until：上端を含まない範囲（0以上5未満）"},{"display":"for (i in 5 downTo 1) println(i)","input":"for (i in 5 downTo 1) println(i)","annotation":"downTo：降順の範囲"},{"display":"for (i in 0..10 step 2) println(i)","input":"for (i in 0..10 step 2) println(i)","annotation":"step：刻み幅（正の刻み幅を指定）"},{"display":"for ((index, value) in items.withIndex()) { println(\"$index: $value\") }","input":"for ((index, value) in items.withIndex()) { println(\"$index: $value\") }","annotation":"withIndex()：添字と値"},{"display":"while (count < 5) { count++ }","input":"while (count < 5) { count++ }","annotation":"while：条件が真の間"},{"display":"do { count++ } while (count < 5)","input":"do { count++ } while (count < 5)","annotation":"do / while：最低1回実行"},{"display":"if (done) break","input":"if (done) break","annotation":"break：ループを抜ける（ループ内）"},{"display":"if (skip) continue","input":"if (skip) continue","annotation":"continue：次の反復へ（ループ内）"},{"display":"fun add(a: Int, b: Int): Int { return a + b }","input":"fun add(a: Int, b: Int): Int { return a + b }","annotation":"fun 名前(引数): 型：戻り値ありの関数"},{"display":"fun greet(name: String) { println(name) }","input":"fun greet(name: String) { println(name) }","annotation":"Unitの関数：意味のある結果を返さない"},{"display":"fun double(n: Int) = n * 2","input":"fun double(n: Int) = n * 2","annotation":"式本体：単一式の関数（戻り値型を推論可能）"},{"display":"fun greet(name: String = \"Guest\") { println(name) }","input":"fun greet(name: String = \"Guest\") { println(name) }","annotation":"デフォルト引数：省略時の値"},{"display":"greet(name = \"Pomo\")","input":"greet(name = \"Pomo\")","annotation":"名前付き引数：引数名を指定"},{"display":"fun sum(vararg values: Int): Int = values.sum()","input":"fun sum(vararg values: Int): Int = values.sum()","annotation":"vararg：可変長引数"},{"display":"val numbers = intArrayOf(1, 2); val total = sum(*numbers)","input":"val numbers = intArrayOf(1, 2); val total = sum(*numbers)","annotation":"*配列：可変長引数へ展開（スプレッド演算子）"},{"display":"return result","input":"return result","annotation":"return 値：値を返して終了"},{"display":"fun outer() { fun inner() {}; inner() }","input":"fun outer() { fun inner() {}; inner() }","annotation":"ローカル関数：関数内に関数を定義"},{"display":"var name: String? = null","input":"var name: String? = null","annotation":"型?：nullを許容（String等の非null型にはnullを代入不可）"},{"display":"val length: Int? = name?.length","input":"val length: Int? = name?.length","annotation":"?.：安全呼び出し（nullなら結果はnull）"},{"display":"val displayName = name ?: \"Guest\"","input":"val displayName = name ?: \"Guest\"","annotation":"?:：Elvis演算子（左辺がnullの場合のみ右辺）"},{"display":"val actual = name ?: return","input":"val actual = name ?: return","annotation":"?: return：nullなら早期return（関数内で戻り値型に合わせて使用）"},{"display":"val length = name!!.length","input":"val length = name!!.length","annotation":"!!：非nullアサーション（nullなら例外）"},{"display":"if (name != null) { println(name.length) }","input":"if (name != null) { println(name.length) }","annotation":"nullチェック：スマートキャスト（途中で変化しないと判断できる等の条件が必要）"},{"display":"name?.let { println(it.length) }","input":"name?.let { println(it.length) }","annotation":"?.let：非null時だけ処理（letは標準ライブラリ関数）"},{"display":"val items = arrayOf(\"A\", \"B\")","input":"val items = arrayOf(\"A\", \"B\")","annotation":"arrayOf：配列（標準ライブラリ）"},{"display":"val nums = intArrayOf(1, 2, 3)","input":"val nums = intArrayOf(1, 2, 3)","annotation":"intArrayOf：IntArray"},{"display":"val nums = Array(3) { 0 }","input":"val nums = Array(3) { 0 }","annotation":"Array(長さ) { 初期値 }：長さを指定した配列（この例はArray<Int>）"},{"display":"val first = items[0]","input":"val first = items[0]","annotation":"items[i]：要素アクセス（範囲外では例外）"},{"display":"val n = items.size","input":"val n = items.size","annotation":"size：要素数"},{"display":"val names = listOf(\"A\", \"B\")","input":"val names = listOf(\"A\", \"B\")","annotation":"listOf：読み取り専用List（完全な不変性の保証とは別）"},{"display":"val names = mutableListOf(\"A\", \"B\")","input":"val names = mutableListOf(\"A\", \"B\")","annotation":"mutableListOf：変更可能List（valでも要素の変更は可能）"},{"display":"names.add(\"C\")","input":"names.add(\"C\")","annotation":"add：要素追加（MutableList等）"},{"display":"names[0] = \"New\"","input":"names[0] = \"New\"","annotation":"添字への代入：要素更新（MutableList・配列等）"},{"display":"val tags = setOf(\"A\", \"B\")","input":"val tags = setOf(\"A\", \"B\")","annotation":"setOf：重複しない集合"},{"display":"val tags = mutableSetOf(\"A\")","input":"val tags = mutableSetOf(\"A\")","annotation":"mutableSetOf：変更可能な集合"},{"display":"val scores = mapOf(\"Pomo\" to 100)","input":"val scores = mapOf(\"Pomo\" to 100)","annotation":"mapOf / to：キーと値の対応（toはPairを作る標準関数）"},{"display":"val scores = mutableMapOf<String, Int>()","input":"val scores = mutableMapOf<String, Int>()","annotation":"mutableMapOf：変更可能Map"},{"display":"scores[\"Pomo\"] = 120","input":"scores[\"Pomo\"] = 120","annotation":"map[key] = value：Mapに追加・更新（MutableMap）"},{"display":"val score = scores[\"Pomo\"]","input":"val score = scores[\"Pomo\"]","annotation":"map[key]：Mapの値を取得（キーがなければ通常null）"},{"display":"val score = scores.getOrDefault(\"Pomo\", 0)","input":"val score = scores.getOrDefault(\"Pomo\", 0)","annotation":"getOrDefault：キーがなければ既定値（登録値がnullの場合はそのnullを返す）"},{"display":"val double = { x: Int -> x * 2 }","input":"val double = { x: Int -> x * 2 }","annotation":"{ 引数 -> 本体 }：ラムダ式"},{"display":"val double: (Int) -> Int = { it * 2 }","input":"val double: (Int) -> Int = { it * 2 }","annotation":"it：単一引数の暗黙名（引数を明示しない単一引数ラムダ） / (引数型) -> 戻り値型：関数型"},{"display":"names.forEach(::println)","input":"names.forEach(::println)","annotation":"::関数：関数参照"},{"display":"val result = names.filter { it.length >= 3 }","input":"val result = names.filter { it.length >= 3 }","annotation":"filter：絞り込み / 末尾ラムダ：最後の関数型引数を括弧外へ"},{"display":"val result = names.map { it.uppercase() }","input":"val result = names.map { it.uppercase() }","annotation":"map：各要素を変換"},{"display":"names.forEach { println(it) }","input":"names.forEach { println(it) }","annotation":"forEach：各要素に処理"},{"display":"val result = names.find { it.startsWith(\"A\") }","input":"val result = names.find { it.startsWith(\"A\") }","annotation":"find：最初の一致（なければnull）"},{"display":"val ok = names.any { it.isEmpty() }","input":"val ok = names.any { it.isEmpty() }","annotation":"any：1つでも条件を満たすか"},{"display":"val ok = names.all { it.isNotEmpty() }","input":"val ok = names.all { it.isNotEmpty() }","annotation":"all：すべて条件を満たすか（空コレクションではtrue）"},{"display":"val result = names.sortedBy { it.length }","input":"val result = names.sortedBy { it.length }","annotation":"sortedBy：指定値で並べ替え"},{"display":"val groups = names.groupBy { it.length }","input":"val groups = names.groupBy { it.length }","annotation":"groupBy：指定キーで分類"},{"display":"val result = names.asSequence().filter { it.length >= 3 }.toList()","input":"val result = names.asSequence().filter { it.length >= 3 }.toList()","annotation":"asSequence：遅延処理するSequence"},{"display":"val result = names.filter { it.length >= 3 }.map { it.uppercase() }","input":"val result = names.filter { it.length >= 3 }.map { it.uppercase() }","annotation":"処理の連結：絞り込みと変換"},{"display":"class User(val name: String, var age: Int) { fun greet() = \"こんにちは、$name\"; fun birthday() { age++ } }","input":"class User(val name: String, var age: Int) { fun greet() = \"こんにちは、$name\"; fun birthday() { age++ } }","annotation":"class / 主コンストラクター：クラス定義"},{"display":"val user = User(\"Pomo\", 20)","input":"val user = User(\"Pomo\", 20)","annotation":"インスタンス作成：クラスのインスタンス（newを書かない）"},{"display":"class User(val name: String)","input":"class User(val name: String)","annotation":"valプロパティ：読み取り専用プロパティ"},{"display":"class User(var age: Int)","input":"class User(var age: Int)","annotation":"varプロパティ：変更可能なプロパティ"},{"display":"class User(val age: Int) { init { require(age >= 0) } }","input":"class User(val age: Int) { init { require(age >= 0) } }","annotation":"init：初期化処理"},{"display":"class User(val name: String) { constructor() : this(\"Guest\") }","input":"class User(val name: String) { constructor() : this(\"Guest\") }","annotation":"constructor / this：副コンストラクター"},{"display":"this.name = name","input":"this.name = name","annotation":"this：現在のインスタンス（代入先はvar等の変更可能なプロパティ）"},{"display":"val isAdult: Boolean get() = age >= 20","input":"val isAdult: Boolean get() = age >= 20","annotation":"get()：カスタムgetter（クラス内。ageは定義済み）"},{"display":"var age: Int = 0 set(value) { require(value >= 0); field = value }","input":"var age: Int = 0 set(value) { require(value >= 0); field = value }","annotation":"set(value) / field：カスタムsetter（fieldはアクセサー内のバッキングフィールド）"},{"display":"open class Animal","input":"open class Animal","annotation":"open class：継承可能なクラス（通常のクラスは既定でfinal）"},{"display":"class Dog : Animal()","input":"class Dog : Animal()","annotation":": 親クラス()：クラス継承"},{"display":"open class Animal { open fun speak() {} }","input":"open class Animal { open fun speak() {} }","annotation":"open fun：オーバーライド可能なメンバー"},{"display":"class Dog : Animal() { override fun speak() { println(\"わん\") } }","input":"class Dog : Animal() { override fun speak() { println(\"わん\") } }","annotation":"override fun：オーバーライド（親側に対応するopen等のメンバーが必要）"},{"display":"abstract class Animal { abstract fun speak() }","input":"abstract class Animal { abstract fun speak() }","annotation":"abstract class / fun：抽象クラス・抽象関数"},{"display":"interface Greeter { fun greet(): String }","input":"interface Greeter { fun greet(): String }","annotation":"interface：インターフェース"},{"display":"class User(val name: String) : Greeter { override fun greet() = \"こんにちは、$name\" }","input":"class User(val name: String) : Greeter { override fun greet() = \"こんにちは、$name\" }","annotation":": インターフェース：実装"},{"display":"super.speak()","input":"super.speak()","annotation":"super：親の実装を呼ぶ（対応する実装があるメンバー内）"},{"display":"public class User","input":"public class User","annotation":"public：公開（通常の既定値）"},{"display":"internal class Helper","input":"internal class Helper","annotation":"internal：同一モジュール内で公開"},{"display":"protected fun work() {}","input":"protected fun work() {}","annotation":"protected：クラス内部・サブクラス向け（トップレベル宣言には使えない）"},{"display":"private fun helper() {}","input":"private fun helper() {}","annotation":"private：宣言した範囲に限定（トップレベルでは同じファイル内）"},{"display":"data class User(val name: String, val age: Int)","input":"data class User(val name: String, val age: Int)","annotation":"data class：データ用クラス（equals・hashCode・toString・copy等を生成）"},{"display":"val updated = user.copy(age = 21)","input":"val updated = user.copy(age = 21)","annotation":"copy：一部を変えてコピー（浅いコピー。内部参照は共有）"},{"display":"val (name, age) = user","input":"val (name, age) = user","annotation":"分解宣言：コンポーネントを変数へ（componentN関数に基づく）"},{"display":"enum class Status { TODO, DOING, DONE }","input":"enum class Status { TODO, DOING, DONE }","annotation":"enum class：値を限定した列挙型"},{"display":"sealed interface Result { data class Success(val value: String) : Result; data class Failure(val message: String) : Result }","input":"sealed interface Result { data class Success(val value: String) : Result; data class Failure(val message: String) : Result }","annotation":"sealed interface：継承関係を制限した状態型（直接のサブタイプに同一パッケージ・モジュール等の制約）"},{"display":"object Config { val appName = \"App\" }","input":"object Config { val appName = \"App\" }","annotation":"object：名前付きシングルトン"},{"display":"class User { companion object { const val DEFAULT_NAME = \"Guest\" } }","input":"class User { companion object { const val DEFAULT_NAME = \"Guest\" } }","annotation":"companion object：クラスに関連するメンバー（Javaのstaticと完全に同じ仕組みではない）"},{"display":"val greeter = object : Greeter { override fun greet() = \"Hello\" }","input":"val greeter = object : Greeter { override fun greet() = \"Hello\" }","annotation":"object : 型：無名オブジェクト"},{"display":"if (value is String) println(value.length)","input":"if (value is String) println(value.length)","annotation":"is：型判定（条件下でスマートキャスト）"},{"display":"val notString = value !is String","input":"val notString = value !is String","annotation":"!is：指定型でないことを判定"},{"display":"val text = value as String","input":"val text = value as String","annotation":"as：キャスト（型が合わなければ例外）"},{"display":"val text = value as? String","input":"val text = value as? String","annotation":"as?：安全キャスト（型が合わなければnull）"},{"display":"class Box<T>(val value: T)","input":"class Box<T>(val value: T)","annotation":"class Box<T>：型パラメーター付きクラス"},{"display":"fun <T> first(items: List<T>): T = items[0]","input":"fun <T> first(items: List<T>): T = items[0]","annotation":"fun <T>：型パラメーター付き関数（空Listでは例外）"},{"display":"class Box<T : Number>(val value: T)","input":"class Box<T : Number>(val value: T)","annotation":"T : Number：型パラメーターの上限"},{"display":"interface Source<out T> { fun get(): T }","input":"interface Source<out T> { fun get(): T }","annotation":"out T：宣言側の共変（主にTを出力する型）"},{"display":"interface Sink<in T> { fun put(value: T) }","input":"interface Sink<in T> { fun put(value: T) }","annotation":"in T：宣言側の反変（主にTを入力する型）"},{"display":"fun count(items: List<*>) = items.size","input":"fun count(items: List<*>) = items.size","annotation":"List<*>：スタープロジェクション（型引数を特定しない）"},{"display":"fun String.greet() = \"こんにちは、$this\"","input":"fun String.greet() = \"こんにちは、$this\"","annotation":"fun 型.関数：拡張関数（型自体を変更するわけではない。静的に解決）"},{"display":"val n = name.let { it.length }","input":"val n = name.let { it.length }","annotation":"let：対象をitとして処理し結果を返す（通常のit名。ラムダ引数名を変更可能）"},{"display":"val n = name.run { length }","input":"val n = name.run { length }","annotation":"run：対象をthisとして処理し結果を返す（レシーバーなしの形式もある）"},{"display":"val names = mutableListOf<String>().apply { add(\"Pomo\") }","input":"val names = mutableListOf<String>().apply { add(\"Pomo\") }","annotation":"apply：設定して対象自身を返す（対象はthis）"},{"display":"val copy = names.also { println(it.size) }","input":"val copy = names.also { println(it.size) }","annotation":"also：付随処理をして対象自身を返す（対象は通常it）"},{"display":"val n = with(name) { length }","input":"val n = with(name) { length }","annotation":"with：指定対象をthisとして処理（ラムダの結果を返す）"},{"display":"val name by lazy { \"Pomo\" }","input":"val name by lazy { \"Pomo\" }","annotation":"by lazy：初回アクセス時に初期化（委譲プロパティ）"},{"display":"class User { lateinit var name: String }","input":"class User { lateinit var name: String }","annotation":"lateinit var：初期化を後へ延ばす（初期化前アクセスは例外。非nullのvar。プリミティブ相当型等には不可）"},{"display":"val number = try { text.toInt() } catch (e: NumberFormatException) { 0 }","input":"val number = try { text.toInt() } catch (e: NumberFormatException) { 0 }","annotation":"try / catch：例外処理と値の選択（検査例外の捕捉・宣言は強制されない）"},{"display":"try { work() } finally { println(\"後片付け\") }","input":"try { work() } finally { println(\"後片付け\") }","annotation":"finally：後片付け（プロセス強制終了等で実行されない場合もある）"},{"display":"throw IllegalArgumentException(\"説明\")","input":"throw IllegalArgumentException(\"説明\")","annotation":"throw：例外送出"},{"display":"require(age >= 0)","input":"require(age >= 0)","annotation":"require：引数等の前提条件（不成立ならIllegalArgumentException）"},{"display":"check(ready)","input":"check(ready)","annotation":"check：状態の前提条件（不成立ならIllegalStateException）"},{"display":"error(\"想定外の状態\")","input":"error(\"想定外の状態\")","annotation":"error：IllegalStateExceptionを送出（戻り値型はNothing）"},{"display":"resource.use { r -> println(r) }","input":"resource.use { r -> println(r) }","annotation":"use：リソースを自動クローズ（対応するリソース型に使用。プラットフォームに依存）"},{"display":"suspend fun greet() { delay(100); println(\"Hello\") }","input":"suspend fun greet() { delay(100); println(\"Hello\") }","annotation":"suspend fun：中断可能な関数（suspendは言語構文。delayはkotlinx.coroutines。自動的に別スレッドにはならない）"},{"display":"suspend fun work() = coroutineScope { launch { delay(100) } }","input":"suspend fun work() = coroutineScope { launch { delay(100) } }","annotation":"coroutineScope：子の完了を待つスコープ（kotlinx.coroutinesの依存・importが必要）"},{"display":"launch { println(\"実行\") }","input":"launch { println(\"実行\") }","annotation":"launch：結果値のない処理を開始（CoroutineScope内で使用）"},{"display":"val result = async { \"完了\" }","input":"val result = async { \"完了\" }","annotation":"async：結果値のある処理を開始（CoroutineScope内で使用。Deferredを返す）"},{"display":"val message = result.await()","input":"val message = result.await()","annotation":"await：結果を待つ（suspend関数等から呼ぶ）"},{"display":"delay(100)","input":"delay(100)","annotation":"delay：スレッドを占有せず待機（中断可能なコンテキストで使用）"},{"display":"val text = withContext(Dispatchers.IO) { \"完了\" }","input":"val text = withContext(Dispatchers.IO) { \"完了\" }","annotation":"withContext：コンテキストを切り替える（ブロッキングI/O等は適切なDispatcherで実行）"},{"display":"runBlocking { delay(100) }","input":"runBlocking { delay(100) }","annotation":"runBlocking：スレッドをブロックして完了を待つ（通常のsuspend処理から不用意に使わない）"},{"display":"import kotlinx.coroutines.*; suspend fun main() = coroutineScope { val result = async { delay(100); \"完了\" }; println(result.await()) }","input":"import kotlinx.coroutines.*; suspend fun main() = coroutineScope { val result = async { delay(100); \"完了\" }; println(result.await()) }","annotation":"コルーチンの実行例：asyncの結果を待つ（kotlinx-coroutines-coreへの依存が必要）"},{"display":"val result = listOf(1, 2).map { it * 2 }","input":"val result = listOf(1, 2).map { it * 2 }","annotation":"構文とライブラリ：言語機能とAPIの区別（コレクション・スコープ関数は標準ライブラリ。多くのコルーチンAPIは追加ライブラリ）"}],"records":[],"createdAt":"2026-10-23T00:00:00.000Z"}]'::jsonb) WITH ORDINALITY AS t(list, position)
), missing AS (
  SELECT w.owner_id, jsonb_agg(pack.list ORDER BY pack.position) AS lists
  FROM "typle_workspaces" w CROSS JOIN pack
  WHERE jsonb_typeof(w.lists) = 'array' AND NOT EXISTS (
    SELECT 1 FROM jsonb_array_elements(w.lists) saved
    WHERE saved->>'id' = pack.list->>'id' OR lower(btrim(saved->>'name')) = lower(pack.list->>'name'))
  GROUP BY w.owner_id
)
UPDATE "typle_workspaces" w
SET lists = w.lists || missing.lists, revision = w.revision + 1, updated_at = now()
FROM missing
WHERE w.owner_id = missing.owner_id
  AND jsonb_array_length(w.lists) + jsonb_array_length(missing.lists) <= 100
  AND octet_length(w.lists::text) + octet_length(missing.lists::text) <= 896 * 1024;
